(4411029, 635581, 43774, '<td valign="top">Beautiful, artistic and zen-like.</td>', 'Beautiful, artistic and zen-like.', '2008-01-21 15:56:11.000000', NULL, 1),
(4411032, 635673, 43774, '<td valign="top">So clear and gorgeous! Wonderful composition.</td>', 'So clear and gorgeous! Wonderful composition.', '2008-01-21 15:56:32.000000', NULL, 1),
