(4413803, 634348, 43774, '<td valign="top">Nice and sharp and clear. Good composition.</td>', 'Nice and sharp and clear. Good composition.', '2008-01-22 13:09:25.000000', NULL, 1),
(4413804, 635506, 52500, '<td valign="top">This is a nice portrait, but the background is distracting.  I think I would have taken it all to pure white.  As is, it''s very blotchy.</td>', 'This is a nice portrait, but the background is distracting.  I think I would have taken it all to pure white.  As is, it''s very blotchy.', '2008-01-22 13:09:31.000000', NULL, 1),
(4413806, 635734, 59470, '<td valign="top">beautiful - i love how the yellow/orange pops</td>', 'beautiful - i love how the yellow/orange pops', '2008-01-22 13:09:47.000000', NULL, 1),
(4413807, 635269, 56658, '<td valign="top">I love the dramatic angle but am not a fan of the processing. seems a bit too much and i really don''t like the halo around the lighthouse.</td>', 'I love the dramatic angle but am not a fan of the processing. seems a bit too much and i really don''t like the halo around the lighthouse.', '2008-01-22 13:10:19.000000', NULL, 1),
(4413808, 636159, 43774, '<td valign="top">Dramatic sky, I also like the reflections in the water. What I don''t like is that the trees seem cut and pasted, I guess this is where you processed the sky separately from the rest of the image?</td>', 'Dramatic sky, I also like the reflections in the water. What I don''t like is that the trees seem cut and pasted, I guess this is where you processed the sky separately from the rest of the image?', '2008-01-22 13:10:24.000000', NULL, 1),
(4413809, 635926, 43774, '<td valign="top">Lovely blues.</td>', 'Lovely blues.', '2008-01-22 13:10:35.000000', NULL, 1),
(4413811, 632922, 43774, '<td valign="top">A beautiful B&amp;W landscape, those clouds are gorgeous in the way they hug the mountain.</td>', 'A beautiful B&W landscape, those clouds are gorgeous in the way they hug the mountain.', '2008-01-22 13:11:07.000000', NULL, 1),
