INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4421192, 634385, 30982, '<td valign="top">Vintage and evocative.  I love the mountain that quietly appears in the distance.</td>', 'Vintage and evocative.  I love the mountain that quietly appears in the distance.', '2008-01-24 11:47:31.000000', NULL, 1),
(4421200, 633001, 67723, '<td valign="top">This is simply too far done for me.  I''m all for editing that adds punch, but the image still has too look a little more believable than this.</td>', 'This is simply too far done for me.  I''m all for editing that adds punch, but the image still has too look a little more believable than this.', '2008-01-24 11:49:10.000000', NULL, 1),
(4421203, 635697, 30982, '<td valign="top">Wonderful contrast - makes this sing!  The color against the bland stone of the castle.</td>', 'Wonderful contrast - makes this sing!  The color against the bland stone of the castle.', '2008-01-24 11:49:31.000000', NULL, 1),
(4421208, 634489, 30982, '<td valign="top">Your processing makes this feel like it was some time in the 50s.  Adds a sense of mystery to the magesty.</td>', 'Your processing makes this feel like it was some time in the 50s.  Adds a sense of mystery to the magesty.', '2008-01-24 11:50:29.000000', NULL, 1),
(4421212, 635507, 30982, '<td valign="top">Ah, this makes me smile from ear to ear.  Nice choice, Christian!</td>', 'Ah, this makes me smile from ear to ear.  Nice choice, Christian!', '2008-01-24 11:50:59.000000', NULL, 1),
(4421215, 633680, 30982, '<td valign="top">Evokes a sense of impending disaster of sorts.  Love the chocolate brown of that wall behind.  Lovely capture of texture, color, ambience.</td>', 'Evokes a sense of impending disaster of sorts.  Love the chocolate brown of that wall behind.  Lovely capture of texture, color, ambience.', '2008-01-24 11:52:34.000000', NULL, 1),
(4421218, 636081, 30982, '<td valign="top">Very nice shot of this regal beast.  I love the ruffled fur of his backside, and the bokeh is very complimentary, echoing the stripes of the tiger.</td>', 'Very nice shot of this regal beast.  I love the ruffled fur of his backside, and the bokeh is very complimentary, echoing the stripes of the tiger.', '2008-01-24 11:53:10.000000', NULL, 1),
(4421221, 634165, 30982, '<td valign="top">How fun!  Love the people in motion.  The yellow on the lower steps adds a nice touch.</td>', 'How fun!  Love the people in motion.  The yellow on the lower steps adds a nice touch.', '2008-01-24 11:53:59.000000', NULL, 1),
(4421228, 635794, 30982, '<td valign="top">You should sell this to the company (CSC) for the cover of their annual report - seriously.  I LOVE the way the background is just barely there - the high key if that''s what it is.  Excellent capture of a bird in flight and a wonderful presentation.</td>', 'You should sell this to the company (CSC) for the cover of their annual report - seriously.  I LOVE the way the background is just barely there - the high key if that''s what it is.  Excellent capture of a bird in flight and a wonderful presentation.', '2008-01-24 11:55:34.000000', NULL, 1),
(4421230, 634191, 30982, '<td valign="top">Excellent perspective!</td>', 'Excellent perspective!', '2008-01-24 11:56:19.000000', NULL, 1),
(4421233, 634184, 30982, '<td valign="top">This just sings.  Wonderful.  Minimal yet not really.  The touch of sun above, the reflection on the squares (why squares, it makes me wonder?)  Great shot.</td>', 'This just sings.  Wonderful.  Minimal yet not really.  The touch of sun above, the reflection on the squares (why squares, it makes me wonder?)  Great shot.', '2008-01-24 11:57:30.000000', NULL, 1),
(4421236, 634899, 30982, '<td valign="top">Aww, this is incredibly sweet!  An excellent moment captured!</td>', 'Aww, this is incredibly sweet!  An excellent moment captured!', '2008-01-24 11:57:55.000000', NULL, 1),
(4421238, 635840, 30982, '<td valign="top">There''s a lovely conversation here, between the rocks and the two distant trees, but it''s all very hushed, very soft.</td>', 'There''s a lovely conversation here, between the rocks and the two distant trees, but it''s all very hushed, very soft.', '2008-01-24 11:59:10.000000', NULL, 1),
