(4421247, 635882, 30982, '<td valign="top">Amazing light and tones.</td>', 'Amazing light and tones.', '2008-01-24 12:01:01.000000', NULL, 1),
(4421252, 634207, 30982, '<td valign="top">I can almost smell the morning here - nicely seen.</td>', 'I can almost smell the morning here - nicely seen.', '2008-01-24 12:03:08.000000', NULL, 1),
(4421256, 635839, 30982, '<td valign="top">My kind of shot!!  Makes me smile.  I love the softness, the flurry of wings, the grays.  All good.</td>', 'My kind of shot!!  Makes me smile.  I love the softness, the flurry of wings, the grays.  All good.', '2008-01-24 12:04:34.000000', NULL, 1),
