(4424558, 634994, 67152, '<td valign="top">i always thought Ireland was the emerald isle...I guess it is actually the amethyst isle...<br/> <br/>good shot and wonderful capture of the suns rays</td>', 'i always thought Ireland was the emerald isle...I guess it is actually the amethyst isle... good shot and wonderful capture of the suns rays', '2008-01-25 13:48:25.000000', NULL, 1),
(4424566, 634701, 71608, '<td valign="top">WOW, amazing perspective, indeed makes the photo represent the title :)</td>', 'WOW, amazing perspective, indeed makes the photo represent the title :)', '2008-01-25 13:49:20.000000', NULL, 1),
(4424569, 634365, 30982, '<td valign="top">A grand presentation of a lovely and intricate structure - toning suits this perfectly.</td>', 'A grand presentation of a lovely and intricate structure - toning suits this perfectly.', '2008-01-25 13:49:58.000000', NULL, 1),
