(4428659, 635963, 87538, '<td valign="top">This little girl has nowhere to go. You needed more foreground and less background.</td>', 'This little girl has nowhere to go. You needed more foreground and less background.', '2008-01-27 11:56:09.000000', NULL, 1),
(4428661, 635679, 53094, '<td valign="top">Simple but nice.  I like the contrasting colors of the sand and sky.  The bush draws your eye to that spot in the photo.</td>', 'Simple but nice.  I like the contrasting colors of the sand and sky.  The bush draws your eye to that spot in the photo.', '2008-01-27 11:56:36.000000', NULL, 1),
